class Solution {
public:
    int minimizeSum(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        return std::min({nums[n - 1] - nums[2], nums[n - 2] - nums[1], nums[n - 3] - nums[0]});
    }
};

class Solution {
    public int minimizeSum(int[] nums) {
        java.util.Arrays.sort(nums);
        int n = nums.length;
        int opt1 = nums[n - 1] - nums[2];
        int opt2 = nums[n - 2] - nums[1];
        int opt3 = nums[n - 3] - nums[0];
        return Math.min(opt1, Math.min(opt2, opt3));
    }
}

var minimizeSum = function(nums) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    return Math.min(
        nums[n - 1] - nums[2],
        nums[n - 2] - nums[1],
        nums[n - 3] - nums[0]
    );
};
